function serializeStory048(root){function walk(n){if(n.nodeType===3)return n.textContent.replace(/\u00a0/g,' ');if(n.nodeType!==1)return '';if(n.tagName==='BR')return '\n';let text=[...n.childNodes].map(walk).join('');if(['STRONG','B'].includes(n.tagName))return '**'+text+'**';if(n.tagName==='MARK'||n.style?.backgroundColor)return '=='+text+'==';if(['DIV','P','LI'].includes(n.tagName))return text.replace(/\n$/,'')+'\n';return text}return [...root.childNodes].map(walk).join('').replace(/\n$/,'')}
